-- name: test_range_sync_mv_reshard @cloud @sequential
-- Test Point: Build on genuinely shared split files, then split/unshare/merge an aggregate MV with independent keys.
-- Method: Compare base, rewritten and direct sync-index data; assert FINISHED jobs and real layouts.
-- Scope: Shared-data range synchronous MV backfill, double writes and maintenance.

CREATE DATABASE db_${uuid0};

USE db_${uuid0};

shell: exec python3 -c 'exec('"'"'import os,signal\nsignal.alarm(5)\ndirectory=\'"'"'/tmp/range_sync_mv_test_range_sync_mv_reshard_${uuid0}\'"'"'\nos.mkdir(directory,0o700)\nhelper_source=\'"'"'import concurrent.futures\\nimport contextlib\\nimport ctypes\\nimport io\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport signal\\nimport subprocess\\nimport sys\\nimport time\\nfrom urllib.parse import urljoin, urlparse\\ndb = "db_${uuid0}"\\ncfg = None\\nconn = None\\nstage_deadline = 0\\ndef remaining():\\n    seconds = stage_deadline - time.monotonic()\\n    assert seconds > 0, "total stage deadline expired"\\n    return seconds\\ndef connection(database=db):\\n    return pymysql.connect(host=cfg.mysql_host, port=int(cfg.mysql_port), user=cfg.mysql_user,\\n                           password=cfg.mysql_password, database=database, autocommit=True,\\n                           connect_timeout=min(5, remaining()), read_timeout=min(15, remaining()),\\n                           write_timeout=min(15, remaining()))\\ndef q(sql, c=None):\\n    c = conn if c is None else c\\n    c._read_timeout = min(15, remaining())\\n    c._write_timeout = min(15, remaining())\\n    with c.cursor() as cursor:\\n        cursor.execute(sql)\\n        return cursor.fetchall()\\ndef records(sql):\\n    conn._read_timeout = min(15, remaining())\\n    conn._write_timeout = min(15, remaining())\\n    with conn.cursor(pymysql.cursors.DictCursor) as cursor:\\n        cursor.execute(sql)\\n        return cursor.fetchall()\\ndef latest(mv):\\n    rows = records("SHOW ALTER MATERIALIZED VIEW ORDER BY JobId DESC")\\n    return next(r for r in rows if r["RollupIndexName"] == mv)\\ndef supervise(argv, budget=105):\\n    # The wrapper is exec\\\'"'"'ed over the harness shell. Its budget plus this five-second\\n    # descendant shutdown is shorter than the harness\\\'"'"'s 120-second timeout.\\n    libc = ctypes.CDLL(None, use_errno=True)\\n    assert libc.prctl(36, 1, 0, 0, 0) == 0, "cannot enable Linux child subreaping"\\n    child = subprocess.Popen(argv, start_new_session=True)\\n    timed_out = False\\n    try:\\n        try:\\n            status = child.wait(timeout=budget)\\n        except subprocess.TimeoutExpired:\\n            timed_out = True\\n            status = None\\n    finally:\\n        shutdown_deadline = time.monotonic() + 5\\n        for sig in (signal.SIGTERM, signal.SIGKILL):\\n            try:\\n                os.killpg(child.pid, sig)\\n            except ProcessLookupError:\\n                pass\\n            try:\\n                child.wait(timeout=min(2, max(0.01, shutdown_deadline - time.monotonic())))\\n            except subprocess.TimeoutExpired:\\n                if sig == signal.SIGKILL:\\n                    raise\\n        # Subreaping lets the supervisor join grandchildren even when their leader\\n        # was killed while its ThreadPoolExecutor or HTTP request was still running.\\n        while True:\\n            try:\\n                pid, _ = os.waitpid(-child.pid, os.WNOHANG)\\n            except ChildProcessError:\\n                break\\n            if pid == 0:\\n                assert time.monotonic() < shutdown_deadline, "descendants did not terminate and join"\\n                time.sleep(0.01)\\n    assert not timed_out, "total stage timeout: process group terminated and joined"\\n    assert status == 0, "stage failed: process group terminated and joined, status=" + str(status)\\ndef worker(code, cleanup=False):\\n    global cfg, conn, pymysql, requests, stage_deadline\\n    import pymysql\\n    import requests\\n    sys.path.insert(0, os.getcwd())\\n    from lib.sr_sql_lib import StarrocksSQLApiLib\\n    stage_deadline = time.monotonic() + 100\\n    with contextlib.redirect_stdout(io.StringIO()):\\n        cfg = StarrocksSQLApiLib()\\n    conn = connection(database=None if cleanup else db)\\n    cfg.mysql_lib.connector = conn\\n    try:\\n        exec(code, globals())\\n    finally:\\n        if conn.open:\\n            conn.close()\\ndef restore_config():\\n    if state_path.exists():\\n        saved = json.loads(state_path.read_text())\\n        failures = []\\n        for key in ("lake_compaction_disable_ids", "tablet_reshard_enable_tablet_merge"):\\n            try:\\n                q("ADMIN SET FRONTEND CONFIG (" + json.dumps(key) + " = " + json.dumps(saved[key]) + ")")\\n                assert str(records("ADMIN SHOW FRONTEND CONFIG LIKE " + json.dumps(key))[0]["Value"]) == saved[key], key\\n            except Exception as error:\\n                failures.append((key, str(error)))\\n        assert not failures, failures\\n        state_path.unlink()\\ndef remove_helper():\\n    directory = Path(__file__).parent\\n    assert directory.name.startswith("range_sync_mv_"), directory\\n    assert directory.stat().st_uid == os.getuid() and not directory.is_symlink(), directory\\n    Path(__file__).unlink()\\n    directory.rmdir()\\n    print("helper removed")\\nfrom pathlib import Path\\nfrom decimal import Decimal, ROUND_HALF_UP\\ndef layout(index):\\n    db_id = next(int(r[0]) for r in q("SHOW PROC \\\'"'"'/dbs\\\'"'"'") if r[1] == db)\\n    table_id = int(q("SELECT TABLE_ID FROM information_schema.tables_config WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=\\\\"t\\\\"")[0][0])\\n    partitions = records("SHOW PARTITIONS FROM t")\\n    assert len(partitions) == 1, partitions\\n    partition = partitions[0]\\n    path = "/dbs/" + str(db_id) + "/" + str(table_id) + "/partitions/" + str(partition["PartitionId"])\\n    indexes = records("SHOW PROC \\\'"'"'" + path + "\\\'"'"'")\\n    current = max((r for r in indexes if r["IndexName"] == index and r["State"] == "NORMAL"), key=lambda r: int(r["IndexId"]))\\n    tablets = records("SHOW PROC \\\'"'"'" + path + "/" + str(current["IndexId"]) + "\\\'"'"'")\\n    assert len(tablets) == int(current["Tablets"]) > 0, (current, tablets)\\n    return partition, current, tablets\\ndef shared(tablet, version):\\n    nodes = json.loads(tablet["BackendId"])\\n    assert nodes, tablet\\n    rows = q("ADMIN EXECUTE ON " + str(nodes[0]) + " \\\'"'"'System.print(StorageEngine.get_lake_tablet_metadata_json(" + str(tablet["TabletId"]) + ", " + str(version) + "))\\\'"'"'")\\n    meta = json.loads("\\\\n".join(str(r[0]) for r in rows))\\n    assert int(meta["id"]) == int(tablet["TabletId"]) and int(meta["version"]) == int(version), "wrong metadata identity"\\n    # Canonical segment_metas[].shared plus the retained legacy arrays use protobuf JSON names.\\n    def contains_shared(value):\\n        if isinstance(value, dict):\\n            return any((k == "shared" and v is True) or (k in ("shared_segments", "sharedSegments") and any(v)) or contains_shared(v) for k, v in value.items())\\n        return isinstance(value, list) and any(contains_shared(v) for v in value)\\n    return contains_shared(meta.get("rowsets", []))\\ndef watermark():\\n    return int(q("SELECT COALESCE(MAX(JOB_ID),0) FROM information_schema.tablet_reshard_jobs WHERE DB_NAME=DATABASE() AND TABLE_NAME=\\\\"t\\\\"")[0][0])\\ndef finish(after, kind, deadline):\\n    while True:\\n        jobs = records("SELECT JOB_ID, JOB_STATE, ERROR_MESSAGE FROM information_schema.tablet_reshard_jobs WHERE DB_NAME=DATABASE() AND TABLE_NAME=\\\\"t\\\\" AND JOB_TYPE=\\\\"" + kind + "\\\\" AND JOB_ID>" + str(after))\\n        assert len(jobs) <= 1, jobs\\n        if jobs:\\n            assert jobs[0]["JOB_STATE"] != "ABORTED", jobs\\n            if jobs[0]["JOB_STATE"] == "FINISHED":\\n                return jobs[0]["JOB_ID"]\\n        assert time.monotonic() < deadline, jobs\\n        time.sleep(0.2)\\ndef check_data(end):\\n    groups = {}\\n    for x in range(1, end + 1):\\n        if x % 7 == 0:\\n            continue\\n        g, v, n = x % 60 + 1, x % 11 + 1, None if x % 4 == 0 else x % 13\\n        groups.setdefault(g, []).append((v,n))\\n    q("SET enable_materialized_view_rewrite=false")\\n    q("SET enable_sync_materialized_view_rewrite=false")\\n    _, current_index, _ = layout("mv_sum")\\n    populated = q("SELECT _tablet_id_, COUNT(*) FROM mv_sum [_SYNC_MV_] GROUP BY _tablet_id_")\\n    assert populated and all(int(row[1]) > 0 for row in populated), populated\\n    if int(current_index["Tablets"]) > 1:\\n        assert len(populated) >= 2, "global aggregate must span populated MV tablet ranges"\\n    combined = [row for values in groups.values() for row in values]\\n    specs = [\\n        ("mv_sum", "SUM(v), COUNT(n)", "SUM(mv_sum_v), SUM(mv_count_n)", lambda rows: (sum(v for v,n in rows), sum(n is not None for v,n in rows))),\\n        ("mv_min", "MIN(v)", "MIN(mv_min_v)", lambda rows: (min(v for v,n in rows),)),\\n        ("mv_max", "MAX(v)", "MAX(mv_max_v)", lambda rows: (max(v for v,n in rows),)),\\n        ("mv_bitmap", "COUNT(DISTINCT v)", "BITMAP_UNION_COUNT(mv_bitmap_union_v)", lambda rows: (len({v for v,n in rows}),)),\\n        ("mv_hll", "HLL_UNION_AGG(HLL_HASH(v))", "HLL_UNION_AGG(mv_hll_union_v)", lambda rows: (len({v for v,n in rows}),)),\\n        ("mv_bagg", "COUNT(DISTINCT n)", "BITMAP_UNION_COUNT(mv_bitmap_union_n)", lambda rows: (len({n for v,n in rows if n is not None}),)),\\n        ("mv_avg", "CAST(ROUND(AVG(v),6) AS DECIMAL(18,6))", "CAST(ROUND(AVG_MERGE(mv_average_value),6) AS DECIMAL(18,6))", lambda rows: ((Decimal(sum(v for v,n in rows))/len(rows)).quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP),)),\\n    ]\\n    for mv, base_expr, direct_expr, reduce in specs:\\n        q("SET query_including_mv_names = " + json.dumps(mv))\\n        expected = tuple((g,) + reduce(rows) for g, rows in sorted(groups.items()))\\n        base = "SELECT g," + base_expr + " FROM t WHERE filter_col>0 GROUP BY g ORDER BY g"\\n        direct = "SELECT g," + direct_expr + " FROM " + mv + " [_SYNC_MV_] GROUP BY g ORDER BY g"\\n        q("SET enable_materialized_view_rewrite=false")\\n        q("SET enable_sync_materialized_view_rewrite=false")\\n        assert q(base) == expected, (mv, "base", q(base), expected)\\n        assert q(direct) == expected, (mv, "direct", q(direct), expected)\\n        q("SET enable_materialized_view_rewrite=true")\\n        q("SET enable_sync_materialized_view_rewrite=true")\\n        cfg.check_hit_materialized_view(base, mv)\\n        assert q(base) == expected, (mv, "rewritten", q(base), expected)\\n        global_expected = (reduce(combined),)\\n        global_base = "SELECT " + base_expr + " FROM t WHERE filter_col>0"\\n        global_direct = "SELECT " + direct_expr + " FROM " + mv + " [_SYNC_MV_]"\\n        q("SET enable_materialized_view_rewrite=false")\\n        q("SET enable_sync_materialized_view_rewrite=false")\\n        assert q(global_base) == global_expected, (mv, "global base", q(global_base), global_expected)\\n        assert q(global_direct) == global_expected, (mv, "global direct", q(global_direct), global_expected)\\n        q("SET enable_materialized_view_rewrite=true")\\n        q("SET enable_sync_materialized_view_rewrite=true")\\n        cfg.check_hit_materialized_view(global_base, mv)\\n        assert q(global_base) == global_expected, (mv, "global rewritten", q(global_base), global_expected)\\n        q(\\\'"'"'SET query_including_mv_names = ""\\\'"'"')\\n    q("SET enable_materialized_view_rewrite=false")\\n    q("SET enable_sync_materialized_view_rewrite=false")\\n    assert q("SELECT COUNT(*) FROM t") == ((end,),)\\nstate_path = Path(__file__).parent / "config.json"\\nHAS_CONFIG = True\\nif __name__ == "__main__":\\n    if sys.argv[1] == "--worker":\\n        worker(sys.argv[2].replace("__NL__", "\\\\n"), cleanup=len(sys.argv) == 4)\\n    elif sys.argv[1] == "--cleanup":\\n        if HAS_CONFIG and state_path.exists():\\n            supervise([sys.executable, __file__, "--worker", "restore_config()", "--cleanup"])\\n        remove_helper()\\n    else:\\n        supervise([sys.executable, __file__, "--worker", sys.argv[1]])\\n\'"'"'\nfd=os.open(directory+"/helper.py",os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)\nwith os.fdopen(fd,"w") as out:\n    out.write(helper_source)\nprint("helper installed")\n'"'"')'

