SET enable_range_distribution = true;

CREATE TABLE t (id INT NOT NULL, g INT NOT NULL, v BIGINT, n BIGINT, filter_col INT)
DUPLICATE KEY(id) ORDER BY(id) PROPERTIES("replication_num" = "1");

-- Save both live FE values before mutation; CLEANUP restores them on any failed oracle. Compaction is frozen only for this unique table.

